#!/usr/bin/env python3
"""Generates the v59+ themes (Dusk, seasonal and meme looks) and writes them into index.html between the two marker comments.
Run it after editing a theme below:  python3 tools/gen-themes.py
It also checks WCAG contrast for every theme and refuses to write anything that falls short.
To add a theme: add an entry to THEMES, then add [key, label] to the THEMES list and the key to the applySkin() regex in index.html."""
import os, re, sys, urllib.parse
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
START, END = '/* ===== v59 themes: generated by tools/gen-themes.py, do not edit by hand ===== */', '/* ===== end v59 themes ===== */'

def lum(h):
    h = h.lstrip('#'); r, g, b = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    f = lambda c: c / 12.92 if c <= .03928 else ((c + .055) / 1.055) ** 2.4
    return .2126 * f(r) + .7152 * f(g) + .0722 * f(b)
def cr(a, b):
    la, lb = sorted([lum(a), lum(b)], reverse=True); return (la + .05) / (lb + .05)
def svg(s):
    return 'url("data:image/svg+xml,' + urllib.parse.quote(s, safe="/:=' ").replace('%20', ' ').replace('"', "'") + '")'

DARK = dict(blue='#8fbcf5', green='#9fdcb4', red='#f09a92', white='#eef0f6', silver='#c3cfdc', rose='#f0adc4', azure='#7fd0e6', prism='#bfb0f0', gold='#e8cf8c', purple='#b5a5ee', black='#d6dfea', warn='#e8c070', ok='#9fdcb4')
LIGHT = dict(blue='#2a67d8', green='#16805a', red='#c8344d', white='#7d86ab', silver='#5f6888', rose='#b8336f', azure='#137b9c', prism='#7a3cc0', gold='#8f6a0a', purple='#6a49c8', black='#2b2f45', warn='#a85b00', ok='#16805a')

dots = lambda col, n, w, h, rmax: ''.join("<circle cx='%d' cy='%d' r='%.1f' fill='%s' fill-opacity='%.2f'/>" % ((i * 53) % w, (i * 97) % h, 1 + (i % 3) * rmax / 3, col, .35 + (i % 4) * .15) for i in range(n))
leaf = lambda col, x, y, r: "<path transform='translate(%d %d) rotate(%d)' d='M0 0C6 -8 14 -6 16 0C14 8 6 10 0 0Z' fill='%s' fill-opacity='.55'/>" % (x, y, r, col)
paw = lambda col, x, y: "<g fill='%s' fill-opacity='.22' transform='translate(%d %d)'><ellipse cx='0' cy='4' rx='6' ry='5'/><circle cx='-7' cy='-4' r='2.6'/><circle cx='-2.5' cy='-8' r='2.6'/><circle cx='2.5' cy='-8' r='2.6'/><circle cx='7' cy='-4' r='2.6'/></g>" % (col, x, y)

THEMES = [
 dict(key='Dusk', dark=True, bg='#15131b', surface='#1e1b26', surface2='#282432', ink='#ece8f3', mute='#b8b1c6', line='rgba(178,164,214,.24)', accent='#b7a5e3', ink2='#191425', hero1='#2a2638', glow='rgba(183,165,227,.20)',
      html="radial-gradient(640px 420px at 50% -8%,rgba(150,132,196,.14),transparent 70%),linear-gradient(180deg,#19171f,#100e15) fixed", base='#121017', head='"Cormorant Garamond",Georgia,serif', eyebrow='#cfc7e2'),
 dict(key='Harvest', dark=True, bg='#1a110a', surface='#271a0f', surface2='#342213', ink='#f7ead6', mute='#cdb79a', line='rgba(232,150,60,.32)', accent='#f0a24a', ink2='#1d0f03', hero1='#3a2414', glow='rgba(240,162,74,.34)',
      html="radial-gradient(560px 380px at 8% 100%,rgba(220,110,30,.28),transparent 70%),radial-gradient(520px 420px at 100% 0,rgba(150,60,30,.26),transparent 70%),linear-gradient(180deg,#24160c,#120a05) fixed", base='#120a05', head='"Cormorant Garamond",Georgia,serif', eyebrow='#f0cfa0',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='260' height='260'>" + leaf('#e07a2c', 30, 40, 20) + leaf('#c2452a', 150, 90, 70) + leaf('#e8b04a', 220, 200, 140) + leaf('#a8531f', 70, 190, 200) + "</svg>")),
 dict(key='Solstice', dark=True, bg='#080d1f', surface='#101a36', surface2='#18264a', ink='#eef2ff', mute='#aebbe0', line='rgba(240,205,120,.30)', accent='#f2cf72', ink2='#161002', hero1='#1a2a58', glow='rgba(242,207,114,.30)',
      html="radial-gradient(600px 400px at 90% 0,rgba(80,200,170,.18),transparent 70%),radial-gradient(520px 420px at 0 100%,rgba(110,90,220,.22),transparent 70%),linear-gradient(180deg,#0d1530,#060914) fixed", base='#060914', head='"Cormorant Garamond",Georgia,serif', eyebrow='#d9e0f7',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='300' height='300'>" + dots('#fff6d8', 26, 300, 300, 2) + "</svg>")),
 dict(key='Blossom', dark=False, bg='#fdf1f4', surface='#ffffff', surface2='#f9e0e8', ink='#3a2030', mute='#6f4e61', line='#ecc3d1', accent='#a8325f', ink2='#ffffff', hero1='#f6cfdb', glow='rgba(168,50,95,.28)',
      html="radial-gradient(520px 360px at 0 0,rgba(255,190,210,.55),transparent 70%),radial-gradient(520px 420px at 100% 100%,rgba(190,230,200,.45),transparent 70%),linear-gradient(180deg,#fff6f8,#f8e6ec) fixed", base='#fdf1f4', head='"Cormorant Garamond",Georgia,serif', eyebrow='#7a3a58',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='240' height='240'>" + ''.join("<g transform='translate(%d %d) rotate(%d)'><ellipse rx='6' ry='3.2' fill='#f2a6be' fill-opacity='.55'/></g>" % (x, y, r) for x, y, r in [(30, 30, 20), (120, 70, 80), (200, 30, 140), (70, 150, 40), (180, 190, 110), (20, 220, 170)]) + "</svg>")),
 dict(key='Heatwave', dark=True, bg='#1a0b22', surface='#28122f', surface2='#371a3e', ink='#fff1e6', mute='#e2bfc8', line='rgba(255,140,90,.34)', accent='#ff8a5c', ink2='#220a02', hero1='#4a1e44', glow='rgba(255,138,92,.36)',
      html="radial-gradient(700px 360px at 50% 105%,rgba(255,150,60,.50),transparent 70%),linear-gradient(180deg,#240c30 0%,#3a1240 55%,#6a2644 100%) fixed", base='#1a0b22', head='"Fredoka",system-ui,sans-serif', eyebrow='#ffd2b8',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='400' height='120'><circle cx='320' cy='70' r='46' fill='#ffb066' fill-opacity='.30'/><path d='M0 120V92C60 84 120 98 190 92S320 86 400 94V120Z' fill='#12061a' fill-opacity='.7'/></svg>"), decopos='right bottom/min(480px,100vw) no-repeat'),
 dict(key='Goblin', dark=True, bg='#10150a', surface='#1a2210', surface2='#253016', ink='#eaf3cf', mute='#b5c493', line='rgba(170,220,70,.30)', accent='#b6e03a', ink2='#0d1203', hero1='#2c3a14', glow='rgba(182,224,58,.30)',
      html="radial-gradient(520px 380px at 10% 100%,rgba(120,140,30,.30),transparent 70%),linear-gradient(180deg,#171e0d,#0a0e05) fixed", base='#0a0e05', head='"Archivo Black",system-ui,sans-serif', eyebrow='#d4e8a0',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'>" + dots('#c8e86a', 14, 200, 200, 3) + "<g fill='#d9c9a0' fill-opacity='.18'><path d='M150 60q12-14 24 0z'/><rect x='158' y='60' width='8' height='12'/></g></svg>")),
 dict(key='Raccoon', dark=True, bg='#15161a', surface='#1f2127', surface2='#2a2d35', ink='#ececf0', mute='#b3b6c2', line='rgba(220,200,120,.26)', accent='#e6c85a', ink2='#1a1503', hero1='#33363f', glow='rgba(230,200,90,.28)',
      html="radial-gradient(520px 380px at 90% 0,rgba(120,125,145,.22),transparent 70%),linear-gradient(180deg,#1b1c21,#0f1013) fixed", base='#0f1013', head='"Fredoka",system-ui,sans-serif', eyebrow='#dcdde6',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'>" + paw('#e6e6f0', 40, 50) + paw('#e6e6f0', 150, 110) + paw('#e6e6f0', 70, 180) + "</svg>")),
 dict(key='Vaporwave', dark=True, bg='#17093a', surface='#241250', surface2='#321a66', ink='#fdeeff', mute='#d3b6ee', line='rgba(255,113,206,.38)', accent='#ff71ce', ink2='#26031c', hero1='#3a1c78', glow='rgba(255,113,206,.40)',
      html="radial-gradient(420px 420px at 50% 62%,rgba(255,190,110,.35),transparent 68%),linear-gradient(180deg,#1d0b48 0%,#3a1470 58%,#0e3b5e 100%) fixed", base='#17093a', head='"IBM Plex Mono",ui-monospace,monospace', eyebrow='#8ff3ff',
      deco="repeating-linear-gradient(0deg,rgba(1,205,254,.30) 0 1px,transparent 1px 28px),repeating-linear-gradient(90deg,rgba(1,205,254,.22) 0 1px,transparent 1px 36px)", decopos='bottom/100% 30vh no-repeat', mono=True),
 dict(key='Dialup', dark=False, bg='#bcc2c8', surface='#d4d0c8', surface2='#c0bcb4', ink='#101018', mute='#3c3c48', line='#808080', accent='#0a0a80', ink2='#ffffff', hero1='#a8aeb8', glow='rgba(10,10,128,.30)',
      html="linear-gradient(180deg,#00807f,#006868) fixed", base='#00807f', head='"IBM Plex Mono",ui-monospace,monospace', eyebrow='#101018', mono=True, bevel=True),
 dict(key='Grass', dark=False, bg='#eaf6d8', surface='#ffffff', surface2='#d9eec0', ink='#1b2a10', mute='#455a30', line='#b6d68f', accent='#2a7a24', ink2='#ffffff', hero1='#c8e6a0', glow='rgba(42,122,36,.28)',
      html="linear-gradient(180deg,#f3fbe4,#dcf0bf) fixed", base='#eaf6d8', head='"Fredoka",system-ui,sans-serif', eyebrow='#2f5a22',
      deco=svg("<svg xmlns='http://www.w3.org/2000/svg' width='160' height='60'>" + ''.join("<path d='M%d 60Q%d 30 %d 8Q%d 34 %d 60Z' fill='#4ea03a' fill-opacity='.55'/>" % (x, x + 2, x + 6 + (x % 5), x + 8, x + 12) for x in range(0, 160, 14)) + "</svg>"), decopos='bottom/160px 60px repeat-x'),
 dict(key='Loaf', dark=False, bg='#fbf0db', surface='#fffaf0', surface2='#f4e2c0', ink='#35261a', mute='#6a5340', line='#e2c692', accent='#9a4a0c', ink2='#ffffff', hero1='#f1d49e', glow='rgba(154,74,12,.28)',
      html="radial-gradient(520px 380px at 100% 0,rgba(240,160,70,.30),transparent 70%),linear-gradient(180deg,#fdf5e4,#f6e6c6) fixed", base='#fbf0db', head='"Fredoka",system-ui,sans-serif', eyebrow='#7a4a20',
      deco="repeating-linear-gradient(115deg,rgba(190,110,40,.07) 0 18px,transparent 18px 46px)"),
]
LABELS = {}
def css(t):
    k = t['key']; s = 'html[data-skin="%s"]' % k; P = LIGHT if not t['dark'] else DARK
    v = '--bg:%s;--surface:%s;--surface2:%s;--ink:%s;--mute:%s;--line:%s;--accent:%s;--accent-ink:%s;--hero1:%s;--glow:%s;' % (t['bg'], t['surface'], t['surface2'], t['ink'], t['mute'], t['line'], t['accent'], t['ink2'], t['hero1'], t['glow'])
    v += ''.join('--%s:%s;' % (n, c) for n, c in P.items()) + 'color-scheme:%s' % ('dark' if t['dark'] else 'light')
    o = [':root[data-album="%s"]{%s}' % (k, v)]
    o.append('%s{background:%s;background-color:%s;accent-color:%s}' % (s, t['html'], t['base'], t['accent']))
    o.append('%s body{background:transparent;color:var(--ink);font-size:16.5px%s}' % (s, ';font-family:"IBM Plex Mono",ui-monospace,monospace' if t.get('mono') else ''))
    o.append('%s ::selection{background:%s;color:%s}' % (s, t['accent'], t['ink2']))
    o.append('%s :focus-visible{outline:2px solid %s;outline-offset:3px}' % (s, t['accent'] if t['dark'] else t['ink']))
    o.append('%s h2,%s h3{font-family:%s;font-weight:600}' % (s, s, t['head']))
    o.append('%s .eyebrow{color:%s;letter-spacing:.3em}' % (s, t['eyebrow']))
    if t.get('bevel'):
        o.append('%s .card,%s .panel,%s .welcome,%s .rescard,%s .foundcard,%s .aboutdlg{border-radius:0;box-shadow:inset 2px 2px 0 #fff,inset -2px -2px 0 #808080,1px 1px 0 #000}' % ((s,) * 6))
        o.append('%s .btn{border-radius:0;box-shadow:inset 1px 1px 0 #fff,inset -1px -1px 0 #808080}' % s)
    else:
        o.append('%s .card,%s .panel,%s .welcome,%s .rescard,%s .foundcard,%s .aboutdlg{box-shadow:0 0 0 1px %s,0 12px 34px -16px %s}' % ((s,) * 6 + (t['line'], t['glow'])))
    o.append('%s .tabs button[aria-selected="true"],%s .seg button[aria-pressed="true"],%s .cvf .btn.on,%s .cxpb.on,%s .btn[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}' % ((s,) * 5))
    if t.get('deco'):
        pos = t.get('decopos')
        if pos:
            o.append('%s::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:%s %s}' % (s, t['deco'], pos))
        else:
            o.append('%s::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:%s}' % (s, t['deco']))
    return '\n'.join(o)
bad = 0
for t in THEMES:
    checks = [('ink/bg', t['ink'], t['bg'], 7), ('ink/surface', t['ink'], t['surface'], 7), ('mute/surface', t['mute'], t['surface'], 4.5), ('mute/bg', t['mute'], t['bg'], 4.5), ('accent-ink/accent', t['ink2'], t['accent'], 4.5), ('accent/surface', t['accent'], t['surface'], 3)]
    for n, a, b, m in checks:
        r = cr(a, b)
        if r < m:
            bad += 1; print('LOW CONTRAST %s %s %.2f < %s' % (t['key'], n, r, m))
if bad: sys.exit('Fix the contrast problems above first. Nothing written.')
block = START + '\n' + '\n'.join(css(t) for t in THEMES) + '\n' + END
p = os.path.join(root, 'index.html'); h = open(p, encoding='utf-8').read()
if START in h:
    h = re.sub(re.escape(START) + r'.*?' + re.escape(END), lambda m: block, h, flags=re.S)
else:
    h = h.replace('.safelist{display:grid;gap:8px}', block + '\n.safelist{display:grid;gap:8px}', 1)
if '--check' in sys.argv:
    if open(p, encoding='utf-8').read() != h:
        sys.exit('Theme block in index.html is out of date. Run: python3 tools/gen-themes.py')
    print('themes are up to date'); sys.exit(0)
open(p, 'w', encoding='utf-8').write(h)
print('wrote %d themes' % len(THEMES))
